package br.com.omnilog.structures; import java.util.*; public final class FilaDespacho {private final Queue<String> fila=new ArrayDeque<>();public void enfileirar(String p){if(p==null||p.isBlank())throw new IllegalArgumentException("Pedido obrigatório");fila.add(p);}public Optional<String> despachar(){return Optional.ofNullable(fila.poll());}public int tamanho(){return fila.size();}}
